#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;
using UnityEngine;using UnityEngine.UI;using System.Reflection;
using HeartOfTheRain.App.Profile;using HeartOfTheRain.App.Home;using HeartOfTheRain.App.PreLevel;using HeartOfTheRain.App.FirstStart;using HeartOfTheRain.App.Localization;using HeartOfTheRain.App.Celebrations;using HeartOfTheRain.M47;
namespace HeartOfTheRain.Verification {
    public sealed class RainCupVerificationProbe:MonoBehaviour {
        public const string RequestName="HOTR_RunRainCup";
        [Serializable] public sealed class Request {public string runId,mode;}
        [Serializable] public sealed class Report {public string utc,status="RUNNING",mode,runId,unity,scope="Native Rain Cup practice with isolated file profiles and fixed LOCAL time. Programmatic simulated first clears; Auto additionally uses seeded test Axe stock on authored level 11 to verify live model-win integration. Not natural-play/balance or real competition certification. Android taps are recorded separately.";public int checks,x,y;public List<string> passed=new List<string>(),frames=new List<string>(),failures=new List<string>();}
        sealed class FaultRepository:IProfileRepository {
            public IProfileRepository inner;public bool Unavailable,FailBefore,FailAfter,FailWinBefore;
            public PlayerProfile Read(){if(Unavailable)throw new IOException("Injected unavailable profile");return inner.Read();}
            public PlayerProfile Commit(long revision,PlayerProfile next){if(FailBefore||FailWinBefore&&next.rainCups.Any(r=>r.points>0)){FailBefore=false;FailWinBefore=false;throw new IOException("Injected before commit");}var p=inner.Commit(revision,next);if(FailAfter){FailAfter=false;throw new IOException("Injected after commit");}return p;}
        }
        RainCupView PageView=>(RainCupView)typeof(RainCupPage).GetField("view",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(page);
        public Report report;Request request;PlayerProfileHost host;HomePage home;RainCupPage page;HomeLevelFlow flow;FaultRepository client;long now=1000;float deadline;int locale;
        public static string Folder(string id,string mode)=>Path.Combine(Application.persistentDataPath,"RainCupVerification",id,"Evidence",mode);
        string folder=>Folder(request.runId,request.mode);
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){
            var path=Path.Combine(Application.persistentDataPath,RequestName);if(!File.Exists(path))return;var r=JsonUtility.FromJson<Request>(File.ReadAllText(path));File.Delete(path);Guid id;if(r==null||!Guid.TryParseExact(r.runId,"N",out id)||!new[]{"Auto","Tap","Restart","StartCup","ActiveRestart","ExpiredRestart","ClaimedRestart","WonRestart"}.Contains(r.mode))throw new InvalidOperationException("Invalid Cup fixture");
            var first=FindFirstObjectByType<FirstStartPage>();first.reviewAlways=true;var probe=new GameObject("Opt-in isolated Rain Cup verification").AddComponent<RainCupVerificationProbe>();probe.request=r;probe.home=first.home;probe.host=first.home.gameObject.AddComponent<PlayerProfileHost>();if(r.mode=="ActiveRestart")probe.now=4600;if(r.mode=="ExpiredRestart")probe.now=173801;
            string root=Path.Combine(Application.persistentDataPath,"RainCupVerification",r.runId);probe.client=new FaultRepository{inner=new FileProfileRepository(Path.Combine(root,"Client"),()=>{var p=PlayerProfile.New(first.home.GetComponent<HomeLevelFlow>().assets.initialStock);if(r.mode!="Auto"){p.completed=10;p.currentLevel=11;p.stars=10;}else p.tools[1]=100;return p;})};probe.host.VerificationRepository=probe.client;probe.host.VerificationCupClock=()=>probe.now;
            probe.host.VerificationAuthorityFactory=player=>new DevelopmentGiftAuthority(new FileProfileRepository(Path.Combine(root,"GiftAuthority"),()=>new PlayerProfile{playerId=player,coins=0,starting=new int[4],tools=new int[4]}),()=>100,GiftSchedule.Preview());
        }
        IEnumerator Start(){
            report=new Report{utc=DateTime.UtcNow.ToString("o"),mode=request.mode,runId=request.runId,unity=Application.unityVersion};Directory.CreateDirectory(folder);Application.logMessageReceived+=Log;deadline=Time.realtimeSinceStartup+300;locale=GameLocale.Current;
            yield return Wait(()=>FindFirstObjectByType<FirstStartPage>().IsVisible);var first=FindFirstObjectByType<FirstStartPage>();first.Request("skip");first.Request("skip");yield return null;page=home.GetComponent<RainCupPage>();flow=home.GetComponent<HomeLevelFlow>();Check(host.Ready&&!host.IsTransient,"Isolated durable profile attached");
            if(request.mode=="Tap"){
                yield return Capture("Home_Join_Ready");Point(home.GetComponentsInChildren<HomeControlLabel>().First(l=>l.action=="cup"));State("READY_HOME_TAP");yield return Wait(()=>page.IsVisible);yield return Capture("Cup_Join_Ready");Point(page.GetComponentsInChildren<HomeControlLabel>().First(l=>l.action=="join"));State("READY_JOIN_TAP");yield return Wait(()=>host.Service.Read().rainCups.Count==1);Check(host.Cup.View().state=="Active","Actual Join starts one 48-hour cup");yield return Capture("Cup_Joined");page.Request("close");Advance(40);now=173800;host.Refresh();page.Show();yield return Capture("Cup_First_Place");Point(page.GetComponentsInChildren<HomeControlLabel>().First(l=>l.action=="claim"));State("READY_CLAIM_TAP");yield return Wait(()=>host.Service.Read().rainCups[0].state=="Claimed");yield return Wait(()=>!home.RewardRevealPlaying);var p=host.Service.Read();Check(p.coins==3050&&p.stars==40&&p.starting[0]==6&&p.starting[1]==6,"Actual claim grants approved first prize to shared stock");yield return Capture("Cup_First_Prize_Claimed");Point(page.GetComponentsInChildren<HomeControlLabel>().First(l=>l.action=="close"));State("READY_CLOSE_TAP");yield return Wait(()=>!page.IsVisible);yield return Capture("Home_First_Prize");
            }else if(request.mode=="Restart"){
                var p=host.Service.Read();Check(p.coins==3050&&p.stars==40&&p.completed==40&&p.rainCups[0].points==30&&p.rainCups[0].state=="Claimed","First prize survives restart");page.Show();yield return null;page.Request("claim");Check(host.Service.Read().coins==3050&&host.Service.Read().rewards.Count==1,"Restart duplicate claim cannot award twice");yield return Capture("Cup_Claimed_Restart");
            }else if(request.mode=="StartCup"){
                page.Show();page.Request("join");page.Request("close");Advance(11);host.Refresh();page.Show();Check(host.Service.Read().rainCups[0].points==1&&host.Service.Read().coins==1300,"Active score saved with first clear");yield return Capture("Cup_Before_ForceStop");
            }else if(request.mode=="ActiveRestart"){
                var s=host.Cup.View();Check(s.run.points==1&&s.state=="Active"&&host.Cup.Remaining(s)==169200,"Restart preserves score and original end time");page.Show();yield return Capture("Cup_Active_Restart");
            }else if(request.mode=="ExpiredRestart"){
                var s=host.Cup.View();Check(s.state=="Finished"&&s.run.points==1&&s.run.finalRank==5,"Offline expiry freezes final practice standings");page.Show();yield return Capture("Cup_Expired_Restart");page.Request("claim");page.Request("claim");Check(host.Service.Read().coins==1350&&host.Service.Read().rewards.Count==1,"Expired claim credits once");yield return Capture("Cup_Expired_Claimed");
            }else if(request.mode=="ClaimedRestart"||request.mode=="WonRestart"){
                var p=host.Service.Read();Check(p.completed==11&&p.currentLevel==12&&p.stars==11&&p.lives==5&&p.rainCups[0].points==1&&p.rainCups[0].state=="Claimed"&&p.coins==(request.mode=="WonRestart"?1850:1350),"Claimed cup and saved first clear survive rollback/restart without loss");page.Show();yield return Capture("Cup_"+request.mode);
            }else{
                Check(home.State.cupStatus=="0/10","No fixed sample countdown");page.Show();yield return Wait(()=>page.IsVisible);yield return Capture("Cup_Locked");page.Request("close");Advance(10);host.Refresh();page.Show();client.FailBefore=true;page.Request("join");Check(host.Service.Read().rainCups.Count==0,"Failed join save starts no timer");Check(PageView.actionError&&!PageView.error&&PageView.snapshot.canJoin,"Precommit failure preserves Join and retry notice");yield return Capture("Cup_Join_Error");page.Request("retry");client.FailAfter=true;page.Request("join");Check(host.Service.Read().rainCups.Count==1,"Lost join confirmation still creates one Cup");Check(!PageView.actionError&&!PageView.error&&PageView.snapshot.state=="Active","Lost join reply reconciles active state");yield return Capture("Cup_Join_Lost_Reply");page.Request("retry");page.Request("join");Check(host.Service.Read().rainCups.Count==1,"Join retry reconciles original command");
                for(int l=0;l<5;l++){GameLocale.Select(l);page.Request("rewards");yield return Capture("Cup_Rewards_"+GameLocale.Codes[l]);page.Request("standings");yield return Capture("Cup_Standings_"+GameLocale.Codes[l]);}GameLocale.Select(locale);page.Request("close");
                flow.Open(11);var modal=home.GetComponent<PreLevelModal>();modal.Requested("play");yield return Wait(()=>flow.Playing&&!FindFirstObjectByType<GameplayScreen>().ReviewInputBlocked);var game=FindFirstObjectByType<GameplayScreen>();game.playbackSpeed=15;client.FailWinBefore=true;int hits=0;
                while(game&&game.Model.Status=="Playing"&&hits++<300){var anchor=game.Model.Pieces.Values.FirstOrDefault(p=>p.IsAnchor&&p.family!="gem"&&p.family!="power");Check(anchor!=null,"Staged authored-board target exists");game.UseBooster(HeartOfTheRain.M46.BoosterKind.Axe,anchor.x,anchor.y);if(game.Model.Status=="Won"){
                    Check(host.Service.Read().completed==10&&host.Service.Read().rainCups[0].points==0,"Failed model-win save commits neither clear nor point");var error=home.GetComponent<DailyGiftPage>();Check(error.IsVisible,"Model-win save failure offers retry");yield return Capture("Connected_Win_Save_Error");now=173801;error.Request("claim");Check(host.Service.Read().completed==11&&host.Service.Read().rainCups[0].points==1,"Retry after expiry retains original model-win timestamp and point");Check(game.Busy,"Point is saved before visual playback completes");}
                    yield return Wait(()=>!game||!game.Busy);
                }
                Check(game&&game.Model.Status=="Won","Staged authored L11 model win");yield return Wait(()=>VictoryCelebrationPlayer.IsPlaying(home));yield return Capture("Connected_Win_Celebration");yield return Wait(()=>!flow.Playing&&!home.RewardRevealPlaying);Check(home.PresentationVisible&&!modal.IsVisible,"Celebration returns Home without next-level modal");page.Show();Check(host.Cup.View().run.points==1&&host.Cup.View().state=="Finished","Late presentation cannot add or remove event points");yield return Capture("Cup_Finished");client.FailBefore=true;page.Request("claim");Check(host.Service.Read().rewards.Count==0&&PageView.actionError&&!PageView.error&&PageView.snapshot.state=="Finished","Precommit claim failure preserves prize eligibility");client.FailAfter=true;page.Request("claim");Check(host.Service.Read().coins==1850&&host.Service.Read().rewards.Count==1,"Lost claim confirmation still saves one fifth prize");Check(PageView.received&&!PageView.error&&!PageView.actionError&&PageView.snapshot.state=="Claimed","Lost claim reply reconciles collected state and notice");yield return Capture("Cup_Claim_Lost_Reply");page.Request("retry");page.Request("claim");Check(host.Service.Read().coins==1850,"Claim retry cannot award twice");yield return Capture("Cup_Claim_Reconciled");page.Request("close");
                home.NavigationRequested.Invoke("daily");home.NavigationRequested.Invoke("cup");Check(page.IsVisible&&!home.GetComponent<DailyGiftPage>().IsVisible,"Cup closes Daily Gift");home.NavigationRequested.Invoke("wellworks");Check(!page.IsVisible&&home.GetComponent<WellworksPage>().IsVisible,"Wellworks closes Cup");home.NavigationRequested.Invoke("cup");Check(page.IsVisible&&!home.GetComponent<WellworksPage>().IsVisible,"Cup closes Wellworks");page.Request("close");client.Unavailable=true;page.Show();yield return Capture("Cup_Read_Error");client.Unavailable=false;page.Request("retry");Check(host.Service.Read().rainCups[0].state=="Claimed","Read recovery preserves Cup result");page.Request("close");yield return Wait(()=>!home.RewardRevealPlaying);yield return Capture("Home_After_Cup");
            }
            Finish(null);
        }
        void Advance(int target){for(int level=host.Service.Read().completed+1;level<=target;level++){string id=Guid.NewGuid().ToString("N");host.Service.Reserve(id,level,"fixture-first-clear",new int[4],50,1);host.Service.CommitStart(id);host.Service.Win(id,host.Cup.CaptureWinTime());}}
        IEnumerator Wait(Func<bool> ready){while(!ready())yield return null;}
        void Point(Component component){var rt=(RectTransform)component.transform;var c=RectTransformUtility.WorldToScreenPoint(null,rt.TransformPoint(rt.rect.center));report.x=Mathf.RoundToInt(c.x);report.y=Screen.height-Mathf.RoundToInt(c.y);}
        IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.25f);if(Application.isEditor)yield break;yield return new WaitForEndOfFrame();var pixels=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(folder,name+".png"),pixels.EncodeToPNG());Destroy(pixels);report.frames.Add(name+".png");}
        void Check(bool ok,string name){report.checks++;if(!ok)throw new InvalidOperationException(name);report.passed.Add(name);}
        void State(string status){report.status=status;Save();}
        void Save(){File.WriteAllText(Path.Combine(folder,"Report.json"),JsonUtility.ToJson(report,true));}
        void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)Finish(message+"\n"+stack);}
        void Update(){if(report!=null&&!report.status.StartsWith("PASS")&&!report.status.StartsWith("FAIL")&&Time.realtimeSinceStartup>deadline)Finish("Timed out at "+report.status);}
        void Finish(string error){if(report.status.StartsWith("PASS")||report.status.StartsWith("FAIL"))return;Application.logMessageReceived-=Log;report.status=error==null?"PASS_NATIVE_RAIN_CUP":"FAIL_NATIVE_RAIN_CUP";if(error!=null)report.failures.Add(error);GameLocale.Select(locale);Save();}
        void OnDestroy(){Application.logMessageReceived-=Log;}
    }
}
#endif
